/* ── MOTION ──────────────────────────────────────────────────────────────── */
function usePrefersReducedMotion() {
  const [rm, setRm] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const on = () => setRm(mq.matches);
    on();
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return rm;
}
function useParallax(rm) {
  useEffect(() => {
    if (rm) return;
    const move = (e) => {
      const x = (e.clientX / window.innerWidth - 0.5) * 2;
      const y = (e.clientY / window.innerHeight - 0.5) * 2;
      document.documentElement.style.setProperty("--px", x);
      document.documentElement.style.setProperty("--py", y);
    };
    window.addEventListener("mousemove", move, { passive: true });
    return () => window.removeEventListener("mousemove", move);
  }, [rm]);
}
// Reveal-on-scroll (IntersectionObserver). Adds .in when visible.
function useReveal(rm) {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    if (rm) { setShown(true); return; }
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setShown(true); io.disconnect(); } },
      { threshold: 0.14 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [rm]);
  return [ref, shown];
}
const reveal = (shown, rm, delay = 0) =>
  rm ? {} : {
    opacity: shown ? 1 : 0,
    transform: shown ? "translateY(0)" : "translateY(22px)",
    transition: `opacity 0.9s cubic-bezier(.2,.7,.2,1) ${delay}s, transform 1s cubic-bezier(.2,.7,.2,1) ${delay}s`,
  };

/* ── TYPE ATOMS ──────────────────────────────────────────────────────────── */
const Label = ({ children, light, color, style }) => (
  <span style={{
    fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase",
    fontWeight: 400, color: color || (light ? "rgba(240,235,227,0.62)" : T.mid),
    display: "inline-block", ...style,
  }}>{children}</span>
);
// Editorial serif heading. Wrap emphasised words in <i> for the signature italic accent.
const Head = ({ children, light, size = "clamp(30px,4.6vw,52px)", lh = 1.04, style, as: Tag = "h2" }) => (
  <Tag style={{
    fontFamily: SERIF, fontWeight: 300, fontSize: size, lineHeight: lh,
    letterSpacing: "0.005em", color: light ? T.linen : T.ink, margin: 0, ...style,
  }}>{children}</Tag>
);
function Btn({ children, onClick, variant = "solid", full, sm, style }) {
  const base = {
    fontFamily: SANS, fontSize: sm ? 10 : 11, letterSpacing: 2, textTransform: "uppercase",
    fontWeight: 400, padding: sm ? "10px 20px" : "15px 30px", cursor: "pointer",
    width: full ? "100%" : "auto", borderRadius: 0, border: "1px solid",
    transition: "background 0.35s ease, color 0.35s ease, border-color 0.35s ease",
    display: "inline-block", textAlign: "center", lineHeight: 1.1,
  };
  const v = {
    solid: { background: T.ink, color: T.white, borderColor: T.ink },
    light: { background: T.white, color: T.ink, borderColor: T.white },
    ghost: { background: "transparent", color: T.ink, borderColor: T.ink },
    ghostLight: { background: "transparent", color: T.linen, borderColor: "rgba(240,235,227,0.5)" },
  }[variant];
  return <button onClick={onClick} className="ai-btn" style={{ ...base, ...v, ...style }}>{children}</button>;
}
const TextLink = ({ children, onClick, light }) => (
  <button onClick={onClick} className="ai-textlink" style={{
    background: "none", border: "none", padding: "0 0 3px", cursor: "pointer",
    fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase",
    color: light ? T.linen : T.ink, borderBottom: `1px solid ${light ? T.linen : T.ink}`,
  }}>{children}</button>
);

/* ── PHOTO (real image deck + generated plate fallback) ──────────────────── */
function Photo({ pg, color = T.mid, name = "", ratio = "3/4", style, eyebrow,
                 fit = "cover", pos = "center 22%", auto = true }) {
  const rm = usePrefersReducedMotion();
  const imgs = (pg != null && IMG[pg]) ? IMG[pg] : [];
  const [i, setI] = useState(0);
  const [bad, setBad] = useState({});
  useEffect(() => { setI(0); }, [pg]);
  useEffect(() => {
    if (rm || !auto || imgs.length < 2) return;
    const id = setInterval(() => setI((p) => (p + 1) % imgs.length), 3600 + ((pg || 0) % 5) * 240);
    return () => clearInterval(id);
  }, [rm, auto, imgs.length, pg]);
  const okCount = imgs.filter((_, idx) => !bad[idx]).length;
  const plate = {
    position: "relative", width: "100%", aspectRatio: ratio, overflow: "hidden",
    background: `linear-gradient(155deg, ${color}33 0%, ${color}14 60%, ${T.blush} 130%)`,
    ...style,
  };
  return (
    <div style={plate}>
      {imgs.map((src, idx) => bad[idx] ? null : (
        <img key={idx} src={src} alt={idx === 0 ? name : ""} loading="lazy"
          onError={() => setBad((b) => ({ ...b, [idx]: true }))}
          style={{
            position: "absolute", inset: 0, width: "100%", height: "100%",
            objectFit: fit, objectPosition: pos,
            opacity: idx === i ? 1 : 0, transition: rm ? "none" : "opacity 1s ease",
          }} />
      ))}
      {auto && imgs.length > 1 && (
        <div style={{ position: "absolute", bottom: 12, left: 0, right: 0, zIndex: 4,
          display: "flex", gap: 6, justifyContent: "center" }}>
          {imgs.map((_, idx) => (
            <button key={idx} aria-label={`View image ${idx + 1}`}
              onClick={(e) => { e.stopPropagation(); setI(idx); }}
              style={{ width: 6, height: 6, borderRadius: "50%", padding: 0, cursor: "pointer",
                border: "none", background: idx === i ? T.white : "rgba(255,255,255,0.5)",
                boxShadow: "0 0 3px rgba(0,0,0,0.4)", transition: "background 0.3s" }} />
          ))}
        </div>
      )}
      {okCount === 0 && (
        <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column",
          justifyContent: "flex-end", padding: 22 }}>
          <span aria-hidden style={{ position: "absolute", inset: 0, opacity: 0.5,
            background: `linear-gradient(160deg, ${color}30, ${T.blush})` }} />
          <span style={{ position: "relative", fontFamily: SANS, fontSize: 9, letterSpacing: 3,
            textTransform: "uppercase", color: T.mid }}>{eyebrow || "A & I"}</span>
          <span style={{ position: "relative", fontFamily: SERIF, fontStyle: "italic", fontSize: 24,
            lineHeight: 1.1, color: T.ink, marginTop: 4 }}>{name}</span>
        </div>
      )}
    </div>
  );
}

/* ── PRODUCT CARD — hover image-swap + quick-add with inline size selector ── */
function ProductCard({ d, go, addToCart, badge, ratio = "3/4" }) {
  const imgs = IMG[d.pg] || [];
  const [hover, setHover] = useState(false);
  const [pickSize, setPickSize] = useState(false);
  const [added, setAdded] = useState(false);
  const hasSecond = imgs.length > 1;
  const { saved, toggleSaved } = useShop();
  const isSaved = saved.includes(d.pg);
  const left = STOCK(d.pg);
  const sold = SOLDOUT(d.pg);
  const [notified, setNotified] = useState(false);

  const choose = (s) => {
    addToCart(d, s);
    setPickSize(false);
    setAdded(true);
    setTimeout(() => setAdded(false), 1400);
  };

  return (
    <div className="ai-card"
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => { setHover(false); setPickSize(false); }}
      style={{ position: "relative" }}>
      {/* image */}
      <div onClick={() => go("product", d.pg)} style={{ position: "relative", cursor: "pointer",
        width: "100%", aspectRatio: ratio, overflow: "hidden", background: T.blush }}>
        {imgs.length === 0 && (
          <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "flex-end", padding: 18,
            background: `linear-gradient(160deg, ${d.color}30, ${T.blush})` }}>
            <span style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 22, color: T.ink }}>{d.name}</span>
          </div>
        )}
        {imgs[0] && (
          <img src={imgs[0]} alt={d.name} loading="lazy"
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover",
              objectPosition: "center 20%", transition: "opacity .7s ease, transform 1.4s ease",
              opacity: hover && hasSecond ? 0 : 1, transform: hover && !hasSecond ? "scale(1.045)" : "scale(1)" }} />
        )}
        {hasSecond && (
          <img src={imgs[1]} alt="" aria-hidden loading="lazy"
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover",
              objectPosition: "center 20%", transition: "opacity .7s ease",
              opacity: hover ? 1 : 0 }} />
        )}
        {badge && (
          <span style={{ position: "absolute", top: 12, left: 12, fontFamily: SANS, fontSize: 9,
            letterSpacing: 1.5, textTransform: "uppercase", color: T.ink, background: "rgba(251,248,245,0.9)",
            padding: "5px 9px" }}>{badge}</span>
        )}
        <button onClick={(e) => { e.stopPropagation(); toggleSaved(d.pg); }} aria-label={isSaved ? "Saved" : "Save"}
          style={{ position: "absolute", top: 10, right: 10, width: 32, height: 32, borderRadius: "50%", border: "none",
            cursor: "pointer", background: "rgba(251,248,245,0.92)", color: isSaved ? "#a23b2e" : T.ink,
            fontSize: 15, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center",
            transition: "color .2s, transform .2s" }}
          onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.12)")}
          onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1)")}>
          {isSaved ? "\u2665" : "\u2661"}
        </button>
        {sold ? (
          <span style={{ position: "absolute", bottom: 10, left: 12, fontFamily: SANS, fontSize: 9, letterSpacing: 1,
            textTransform: "uppercase", color: T.ink, background: "rgba(251,248,245,0.92)", padding: "4px 8px" }}>
            Sold out
          </span>
        ) : left <= 4 && (
          <span style={{ position: "absolute", bottom: 10, left: 12, fontFamily: SANS, fontSize: 9, letterSpacing: 1,
            textTransform: "uppercase", color: T.linen, background: "rgba(51,48,31,0.85)", padding: "4px 8px" }}>
            Only {left} left
          </span>
        )}

        {/* quick-add overlay */}
        <div className="ai-quick" style={{
          position: "absolute", left: 0, right: 0, bottom: 0, padding: 10,
          transform: hover ? "translateY(0)" : "translateY(101%)",
          transition: "transform .4s cubic-bezier(.3,.8,.3,1)", pointerEvents: hover ? "auto" : "none",
        }}>
          {sold ? (
            <button onClick={(e) => { e.stopPropagation(); setNotified(true); }}
              style={{ width: "100%", background: T.olive, color: T.linen, border: "none", borderRadius: 0, cursor: "pointer",
                fontFamily: SANS, fontSize: 10, letterSpacing: 2, textTransform: "uppercase", padding: "13px 0" }}>
              {notified ? "On the waitlist \u2713" : "Notify me"}
            </button>
          ) : !pickSize ? (
            <button
              onClick={(e) => { e.stopPropagation(); setPickSize(true); }}
              style={{ width: "100%", background: added ? T.olive : T.ink, color: T.white, border: "none",
                borderRadius: 0, cursor: "pointer", fontFamily: SANS, fontSize: 10, letterSpacing: 2,
                textTransform: "uppercase", padding: "13px 0", transition: "background .3s" }}>
              {added ? "Added to bag ✓" : "Add to bag +"}
            </button>
          ) : (
            <div onClick={(e) => e.stopPropagation()} style={{ background: T.white, padding: "10px 10px 8px" }}>
              <div style={{ fontFamily: SANS, fontSize: 9, letterSpacing: 2, textTransform: "uppercase",
                color: T.mid, marginBottom: 8, textAlign: "center" }}>Select size</div>
              <div style={{ display: "flex", gap: 6, justifyContent: "center" }}>
                {SIZES.map((s) => (
                  <button key={s} onClick={() => choose(s)}
                    style={{ flex: 1, padding: "9px 0", cursor: "pointer", fontFamily: SANS, fontSize: 11,
                      color: T.ink, background: "transparent", border: `1px solid ${T.border}`, borderRadius: 0,
                      transition: "background .2s, color .2s" }}
                    onMouseEnter={(e) => { e.currentTarget.style.background = T.ink; e.currentTarget.style.color = T.white; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.color = T.ink; }}>
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* meta */}
      <div onClick={() => go("product", d.pg)} style={{ cursor: "pointer", padding: "13px 2px 0" }}>
        <div style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 19, lineHeight: 1.15, color: T.ink }}>{d.name}</div>
        <div style={{ fontFamily: SANS, fontSize: 12, letterSpacing: 0.5, color: T.mid, marginTop: 5 }}>{peso(d.price)}</div>
      </div>
    </div>
  );
}

/* ── PRODUCT RAIL — category tabs + horizontal scroll ────────────────────── */
function Rail({ go, addToCart, setColFilter }) {
  const tabs = [
    { id: "drop", label: "The Drop", list: FEATURED.concat(DL.filter(d => ![23, 42, 9, 7].includes(d.pg)).slice(0, 8)) },
    { id: "ready", label: "Ready-to-Wear", list: DL.filter(d => d.cat === "ready") },
    { id: "craft", label: "Indian Craft", list: DL.filter(d => d.cat === "craft") },
    { id: "linen", label: "Linen", list: DL.filter(d => d.cat === "linen") },
  ];
  const [tab, setTab] = useState("drop");
  const active = tabs.find(t => t.id === tab);
  const rm = usePrefersReducedMotion();
  const [ref, shown] = useReveal(rm);
  return (
    <section ref={ref} style={{ padding: "clamp(56px,8vw,104px) 0", ...reveal(shown, rm) }}>
      <div style={{ maxWidth: 1380, margin: "0 auto", padding: "0 clamp(20px,4vw,52px)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end",
          flexWrap: "wrap", gap: 18, marginBottom: 30 }}>
          <Head size="clamp(26px,3.6vw,40px)">Shop <i>the edit</i></Head>
          <div style={{ display: "flex", gap: 22, flexWrap: "wrap", alignItems: "center" }}>
            {tabs.map(t => (
              <button key={t.id} onClick={() => setTab(t.id)}
                style={{ background: "none", border: "none", cursor: "pointer", padding: "0 0 4px",
                  fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase",
                  color: tab === t.id ? T.ink : T.mid,
                  borderBottom: `1px solid ${tab === t.id ? T.ink : "transparent"}`, transition: "color .25s" }}>
                {t.label}
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="ai-rail" style={{ display: "flex", gap: 18, overflowX: "auto", scrollSnapType: "x mandatory",
        padding: "0 clamp(20px,4vw,52px) 6px" }}>
        {active.list.slice(0, 12).map(d => (
          <div key={d.pg + tab} style={{ flex: "0 0 clamp(220px,26vw,300px)", scrollSnapAlign: "start" }}>
            <ProductCard d={d} go={go} addToCart={addToCart} badge={CAT_LABEL[d.cat]} />
          </div>
        ))}
      </div>
      <div style={{ maxWidth: 1380, margin: "26px auto 0", padding: "0 clamp(20px,4vw,52px)" }}>
        <TextLink onClick={() => { if (active.id !== "drop") setColFilter(active.id); else setColFilter("all"); go("collection"); }}>
          View all
        </TextLink>
      </div>
    </section>
  );
}

/* ═══ 3D HERO — slide-to-enter gate (Three.js r128) ══════════════════════ */
function ThreeHero({ entered, onEnter, rm }) {
  const mountRef = useRef(null);
  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    let raf, renderer, disposed = false;
    try {
    const renderer_ = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer = renderer_;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    mount.appendChild(renderer.domElement);
    renderer.domElement.style.display = "block";

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x0d0c0b, 0.085);
    const camera = new THREE.PerspectiveCamera(38, mount.clientWidth / mount.clientHeight, 0.1, 100);
    camera.position.set(0, 1.1, 7.2);

    // draped form (lathe profile) — reads as a figure turning under the spotlight
    const profile = [
      [0.06, 2.05], [0.30, 1.78], [0.40, 1.45], [0.30, 1.12],
      [0.42, 0.7], [0.62, 0.15], [0.92, -0.5], [1.24, -1.15],
      [1.46, -1.55], [1.5, -1.62], [0.0, -1.66],
    ].map(p => new THREE.Vector2(p[0], p[1]));
    const gownGeo = new THREE.LatheGeometry(profile, 160);
    const basePos = gownGeo.attributes.position.array.slice(0);
    const satin = new THREE.MeshPhysicalMaterial({
      color: 0xEDE6D8, roughness: 0.42, metalness: 0.0, clearcoat: 0.6,
      clearcoatRoughness: 0.5, side: THREE.DoubleSide, emissive: 0x1a160f, emissiveIntensity: 0.4,
    });
    const gown = new THREE.Mesh(gownGeo, satin);
    gown.castShadow = true; gown.position.y = 0.15; scene.add(gown);

    const refl = new THREE.Mesh(gownGeo, satin.clone());
    refl.material.transparent = true; refl.material.opacity = 0.16; refl.material.depthWrite = false;
    refl.scale.y = -1; refl.position.y = -2.97; scene.add(refl);

    const floor = new THREE.Mesh(
      new THREE.CircleGeometry(14, 64),
      new THREE.MeshStandardMaterial({ color: 0x0a0908, roughness: 0.34, metalness: 0.55 })
    );
    floor.rotation.x = -Math.PI / 2; floor.position.y = -1.55; floor.receiveShadow = true; scene.add(floor);
    const pool = new THREE.Mesh(
      new THREE.CircleGeometry(3.2, 64),
      new THREE.MeshBasicMaterial({ color: 0xC4A96A, transparent: true, opacity: 0.1 })
    );
    pool.rotation.x = -Math.PI / 2; pool.position.y = -1.54; scene.add(pool);

    scene.add(new THREE.HemisphereLight(0x3a3530, 0x05040a, 0.35));
    const key = new THREE.SpotLight(0xfff4e0, 14, 22, Math.PI / 7, 0.55, 1.4);
    key.position.set(0, 8.5, 1.2); key.target.position.set(0, 0, 0);
    key.castShadow = true; key.shadow.mapSize.set(1024, 1024); key.shadow.bias = -0.0004;
    scene.add(key); scene.add(key.target);
    const rimL = new THREE.SpotLight(0xb8a8d4, 5, 20, Math.PI / 5, 0.8, 1.5); rimL.position.set(-6, 3, -3); scene.add(rimL);
    const rimR = new THREE.SpotLight(0xC4A96A, 4, 20, Math.PI / 5, 0.8, 1.5); rimR.position.set(6, 2.5, -2); scene.add(rimR);

    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(2.6, 9, 48, 1, true),
      new THREE.MeshBasicMaterial({ color: 0xfff0d8, transparent: true, opacity: 0.045,
        side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    cone.position.set(0, 3.4, 0.4); scene.add(cone);

    const dustN = 240, dpos = new Float32Array(dustN * 3);
    for (let i = 0; i < dustN; i++) { dpos[i * 3] = (Math.random() - 0.5) * 6; dpos[i * 3 + 1] = Math.random() * 5 - 1; dpos[i * 3 + 2] = (Math.random() - 0.5) * 6; }
    const dustGeo = new THREE.BufferGeometry(); dustGeo.setAttribute("position", new THREE.BufferAttribute(dpos, 3));
    const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({ color: 0xC4A96A, size: 0.018, transparent: true, opacity: 0.5, depthWrite: false }));
    scene.add(dust);

    let mx = 0, my = 0, dragging = false, lastX = 0, dragAz = 0, az = 0;
    const onMove = (e) => { mx = (e.clientX / window.innerWidth - 0.5); my = (e.clientY / window.innerHeight - 0.5); if (dragging) { dragAz += (e.clientX - lastX) * 0.005; lastX = e.clientX; } };
    const onDown = (e) => { dragging = true; lastX = e.clientX; };
    const onUp = () => { dragging = false; };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mousedown", onDown);
    window.addEventListener("mouseup", onUp);

    const clock = new THREE.Clock();
    const animate = () => {
      if (disposed) return;
      raf = requestAnimationFrame(animate);
      const t = clock.getElapsedTime();
      if (!rm) {
        const pos = gownGeo.attributes.position;
        for (let i = 0; i < pos.count; i++) {
          const ix = i * 3, x = basePos[ix], y = basePos[ix + 1], z = basePos[ix + 2];
          const theta = Math.atan2(z, x), r = Math.hypot(x, z);
          const drop = THREE.MathUtils.clamp((1.8 - y) / 3.4, 0, 1);
          const fold = Math.sin(theta * 9 + y * 1.6 + t * 0.9) * 0.05 * drop + Math.sin(theta * 5 - t * 0.6) * 0.03 * drop;
          const nr = r + fold;
          pos.array[ix] = Math.cos(theta) * nr; pos.array[ix + 2] = Math.sin(theta) * nr;
        }
        pos.needsUpdate = true; gownGeo.computeVertexNormals();
        gown.position.y = 0.15 + Math.sin(t * 0.7) * 0.06;
        gown.rotation.y = t * 0.18; refl.rotation.y = gown.rotation.y;
        dust.rotation.y = t * 0.02; dust.material.opacity = 0.35 + Math.sin(t * 1.3) * 0.15;
      }
      const targetAz = (rm ? 0 : t * 0.08) + dragAz + mx * 0.6;
      az += (targetAz - az) * 0.05;
      const rad = 7.0, ty = 1.1 - my * 0.7;
      camera.position.x = Math.sin(az) * rad; camera.position.z = Math.cos(az) * rad;
      camera.position.y += (ty - camera.position.y) * 0.05;
      camera.lookAt(0, 0.25, 0);
      renderer.render(scene, camera);
    };
    animate();

    const onResize = () => {
      if (!mount) return;
      camera.aspect = mount.clientWidth / mount.clientHeight; camera.updateProjectionMatrix();
      renderer.setSize(mount.clientWidth, mount.clientHeight);
    };
    window.addEventListener("resize", onResize);

    return () => {
      disposed = true; cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mousedown", onDown);
      window.removeEventListener("mouseup", onUp);
      window.removeEventListener("resize", onResize);
      try { renderer.dispose(); gownGeo.dispose(); satin.dispose(); } catch (e) {}
      if (renderer.domElement && renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
    };
    } catch (err) {
      // WebGL unavailable — show the dark intro overlay without the 3D scene
      return () => { disposed = true; if (raf) cancelAnimationFrame(raf); };
    }
  }, [rm]);

  // enter on scroll / drag-up / key
  useEffect(() => {
    if (entered) return;
    const trigger = () => onEnter();
    const onWheel = (e) => { if (Math.abs(e.deltaY) > 6) trigger(); };
    let ty0 = null;
    const onTS = (e) => { ty0 = e.touches[0].clientY; };
    const onTM = (e) => { if (ty0 != null && ty0 - e.touches[0].clientY > 28) trigger(); };
    const onKey = (e) => { if (["ArrowDown", "Enter", " ", "PageDown"].includes(e.key)) trigger(); };
    window.addEventListener("wheel", onWheel, { passive: true });
    window.addEventListener("touchstart", onTS, { passive: true });
    window.addEventListener("touchmove", onTM, { passive: true });
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("wheel", onWheel);
      window.removeEventListener("touchstart", onTS);
      window.removeEventListener("touchmove", onTM);
      window.removeEventListener("keydown", onKey);
    };
  }, [entered, onEnter]);

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 300, overflow: "hidden",
      background: "radial-gradient(120% 90% at 50% 30%, #1a1714 0%, #0D0C0B 60%, #060504 100%)",
      transform: entered ? "translateY(-100%)" : "translateY(0)",
      transition: "transform 1.05s cubic-bezier(.76,0,.24,1)",
      pointerEvents: entered ? "none" : "auto",
    }}>
      <div ref={mountRef} style={{ position: "absolute", inset: 0 }} />
      {/* vignette + grain */}
      <div style={{ position: "absolute", inset: 0, pointerEvents: "none",
        background: "radial-gradient(75% 65% at 50% 42%, transparent 40%, rgba(6,5,4,0.55) 100%)" }} />
      {/* brand overlay */}
      <div style={{ position: "absolute", inset: 0, zIndex: 4, pointerEvents: "none",
        display: "flex", flexDirection: "column", justifyContent: "space-between",
        padding: "clamp(22px,4vw,52px)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div style={{ fontFamily: SERIF, fontSize: 26, letterSpacing: 1, color: T.linen }}>
            A <span style={{ color: T.gold, fontStyle: "italic" }}>&amp;</span> I
          </div>
          <div style={{ fontFamily: SANS, fontSize: 9, letterSpacing: 4, textTransform: "uppercase",
            color: "rgba(240,235,227,0.5)", textAlign: "right", lineHeight: 1.7 }}>
            SS'26<br />The Studio
          </div>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: "clamp(70px,12vh,130px)", zIndex: 4, textAlign: "center" }}>
        <div className="ai-rise" style={{ fontFamily: SANS, fontSize: 10, letterSpacing: 5, textTransform: "uppercase",
          color: "rgba(196,169,106,0.85)", animationDelay: ".3s" }}>SS'26 — The Drop</div>
        <div className="ai-rise" style={{ fontFamily: SERIF, fontWeight: 300, color: T.linen, marginTop: 8,
          fontSize: "clamp(40px,7vw,92px)", lineHeight: 0.98, animationDelay: ".5s" }}>
          Made to be<br /><i style={{ color: T.gold }}>moved in.</i>
        </div>
        <button onClick={onEnter} className="ai-rise" style={{ marginTop: 26, cursor: "pointer",
          fontFamily: SANS, fontSize: 10, letterSpacing: 3, textTransform: "uppercase", color: T.ink,
          background: T.linen, border: "none", padding: "14px 32px", animationDelay: ".7s" }}>
          Enter the Collection
        </button>
      </div>
      <button onClick={onEnter} style={{ position: "absolute", bottom: 18, left: "50%", transform: "translateX(-50%)",
        zIndex: 4, background: "none", border: "none", cursor: "pointer",
        fontFamily: SANS, fontSize: 8, letterSpacing: 2, textTransform: "uppercase",
        color: "rgba(240,235,227,0.4)" }}>
        scroll · drag to orbit · click to enter
      </button>
    </div>
  );
}

/* ═══ APP ════════════════════════════════════════════════════════════════ */
export default function App() {
  const rm = usePrefersReducedMotion();
  useParallax(rm);

  const [entered, setEntered] = useState(false);
  const [introGone, setIntroGone] = useState(false);
  const [route, setRoute] = useState({ page: "home", pg: null });
  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [colFilter, setColFilter] = useState("all");
  const [saved, setSaved] = useState([]);
  const [savedOpen, setSavedOpen] = useState(false);

  const go = useCallback((page, pg = null) => {
    setRoute({ page, pg });
    setMenuOpen(false); setSearchOpen(false); setSavedOpen(false);
    window.scrollTo({ top: 0, behavior: rm ? "auto" : "smooth" });
  }, [rm]);

  const addToCart = (d, size) => {
    setCart((c) => [...c, { ...d, size, key: Date.now() + Math.random() }]);
    setCartOpen(true);
  };
  const removeFromCart = (key) => setCart((c) => c.filter((i) => i.key !== key));
  const subtotal = cart.reduce((s, i) => s + i.price, 0);
  const toggleSaved = (pg) => setSaved((s) => s.includes(pg) ? s.filter((x) => x !== pg) : [...s, pg]);

  const enter = useCallback(() => {
    if (entered) return;
    setEntered(true);
    setTimeout(() => setIntroGone(true), 1100);
  }, [entered]);

  const ctx = { rm, go, addToCart, cart, route, setColFilter };

  return (
    <ShopCtx.Provider value={{ saved, toggleSaved }}>
    <div style={{ background: T.bg, minHeight: "100vh", color: T.ink, fontFamily: SANS,
      display: "flex", flexDirection: "column" }}>
      <GlobalStyle />

      {!introGone && <ThreeHero entered={entered} onEnter={enter} rm={rm} />}

      <Announce />
      <Nav go={go} route={route} cartCount={cart.length} onCart={() => setCartOpen(true)}
        onSearch={() => setSearchOpen(true)} menuOpen={menuOpen} setMenuOpen={setMenuOpen}
        setColFilter={setColFilter} savedCount={saved.length} onSaved={() => setSavedOpen(true)} />

      <main style={{ flex: 1 }}>
        {route.page === "home" && <Home {...ctx} />}
        {route.page === "collection" && <Collection {...ctx} colFilter={colFilter} setColFilter={setColFilter} />}
        {route.page === "product" && <Product {...ctx} pg={route.pg} />}
        {route.page === "lookbook" && <Lookbook {...ctx} />}
        {route.page === "about" && <About {...ctx} />}
      </main>

      <Footer go={go} setColFilter={setColFilter} />

      <CartDrawer open={cartOpen} onClose={() => setCartOpen(false)} cart={cart}
        remove={removeFromCart} subtotal={subtotal} go={go} addToCart={addToCart} />
      <SavedDrawer open={savedOpen} onClose={() => setSavedOpen(false)} saved={saved}
        toggleSaved={toggleSaved} go={go} addToCart={addToCart} />
      <SearchOverlay open={searchOpen} onClose={() => setSearchOpen(false)} go={go} />
      <ExitPopup />
    </div>
    </ShopCtx.Provider>
  );
}

/* ── ANNOUNCE BAR (dark olive) ───────────────────────────────────────────── */
function Announce() {
  return (
    <div style={{ background: T.olive, color: T.linen, textAlign: "center", padding: "8px 14px",
      fontFamily: SANS, fontSize: 10, letterSpacing: 2, textTransform: "uppercase",
      display: "flex", alignItems: "center", justifyContent: "center", gap: 28, flexWrap: "wrap" }}>
      <span style={{ opacity: 0.85 }}>Made in India, in small runs</span>
      <span className="ann-hide" style={{ opacity: 0.55 }}>·</span>
      <span className="ann-hide" style={{ opacity: 0.9 }}><Countdown target={DROP_AT} /></span>
      <span className="ann-hide" style={{ opacity: 0.55 }}>·</span>
      <span style={{ opacity: 0.85 }}>India / ₹ INR</span>
    </div>
  );
}

/* ── NAV (centered logo + mega-menu) ─────────────────────────────────────── */
function Nav({ go, route, cartCount, onCart, onSearch, menuOpen, setMenuOpen, setColFilter, savedCount, onSaved }) {
  const [shopOpen, setShopOpen] = useState(false);
  const left = [
    ["SS'26", () => { setColFilter("all"); go("collection"); }, false],
    ["Shop", () => { setColFilter("all"); go("collection"); }, true],
    ["Lookbook", () => go("lookbook"), false],
    ["About", () => go("about"), false],
  ];
  const link = (active) => ({
    fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase",
    fontWeight: 400, color: active ? T.ink : T.mid, background: "none", border: "none",
    cursor: "pointer", padding: 0, transition: "color .25s",
  });
  const cats = [
    ["Ready-to-Wear", "ready"], ["Indian Craft", "craft"], ["Linen", "linen"], ["View All", "all"],
  ];
  return (
    <nav style={{ position: "sticky", top: 0, zIndex: 50, background: "rgba(251,248,245,0.86)",
      backdropFilter: "blur(10px)", WebkitBackdropFilter: "blur(10px)",
      borderBottom: `1px solid ${T.borderSoft}` }}
      onMouseLeave={() => setShopOpen(false)}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center",
        padding: "0 clamp(18px,4vw,48px)", height: 64 }}>
        {/* left links */}
        <div className="nav-links" style={{ display: "flex", gap: 30, alignItems: "center" }}>
          {left.map(([label, fn, isShop]) => (
            <button key={label}
              onMouseEnter={() => setShopOpen(!!isShop)}
              onClick={fn} style={link(false)}>{label}</button>
          ))}
        </div>
        {/* burger (mobile) */}
        <button className="nav-burger" onClick={() => setMenuOpen((m) => !m)} aria-label="Menu"
          style={{ display: "none", background: "none", border: "none", cursor: "pointer", justifySelf: "start",
            fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", color: T.ink }}>
          {menuOpen ? "Close" : "Menu"}
        </button>

        {/* center logo */}
        <button onClick={() => go("home")} style={{ background: "none", border: "none", cursor: "pointer",
          fontFamily: SERIF, fontSize: 30, letterSpacing: 5, color: T.ink, justifySelf: "center", lineHeight: 1 }}>
          A <span style={{ fontStyle: "italic", fontSize: 26 }}>&amp;</span> I
        </button>

        {/* right utilities */}
        <div style={{ display: "flex", gap: 18, alignItems: "center", justifyContent: "flex-end" }}>
          <button onClick={onSearch} className="util" style={link(false)}>Search</button>
          <button onClick={onSaved} className="util" style={link(false)}>Saved ({savedCount})</button>
          <button onClick={() => go("about")} className="util-hide" style={link(false)}>Account</button>
          <button onClick={onCart} style={{ ...link(true) }}>
            Bag{cartCount > 0 ? ` (${cartCount})` : " (0)"}
          </button>
        </div>
      </div>

      {/* mega-menu */}
      <div onMouseEnter={() => setShopOpen(true)}
        style={{ overflow: "hidden", maxHeight: shopOpen ? 360 : 0, transition: "max-height .4s ease",
          borderTop: shopOpen ? `1px solid ${T.borderSoft}` : "none", background: "rgba(251,248,245,0.97)" }}>
        <div style={{ maxWidth: 1380, margin: "0 auto", padding: shopOpen ? "30px clamp(20px,4vw,48px) 36px" : "0",
          display: "grid", gridTemplateColumns: "1fr 1fr 1.4fr", gap: 36 }} className="mega">
          <div>
            <div style={{ fontFamily: SANS, fontSize: 9, letterSpacing: 2, textTransform: "uppercase", color: T.mid, marginBottom: 14 }}>Categories</div>
            {cats.map(([label, id]) => (
              <button key={id} onClick={() => { setColFilter(id); go("collection"); setShopOpen(false); }}
                style={{ display: "block", background: "none", border: "none", cursor: "pointer", padding: "0 0 11px",
                  fontFamily: SERIF, fontSize: 19, color: T.ink, textAlign: "left" }}>{label}</button>
            ))}
          </div>
          <div>
            <div style={{ fontFamily: SANS, fontSize: 9, letterSpacing: 2, textTransform: "uppercase", color: T.mid, marginBottom: 14 }}>Explore</div>
            {[["The Lookbook", () => go("lookbook")], ["Our World", () => go("about")], ["SS'26 — The Drop", () => { setColFilter("all"); go("collection"); }]].map(([label, fn]) => (
              <button key={label} onClick={() => { fn(); setShopOpen(false); }}
                style={{ display: "block", background: "none", border: "none", cursor: "pointer", padding: "0 0 11px",
                  fontFamily: SERIF, fontSize: 19, color: T.ink, textAlign: "left" }}>{label}</button>
            ))}
          </div>
          <div style={{ display: "flex", gap: 14 }} className="mega-imgs">
            {[23, 11].map(pg => {
              const d = DL.find(x => x.pg === pg);
              return (
                <button key={pg} onClick={() => { go("product", pg); setShopOpen(false); }}
                  style={{ flex: 1, background: "none", border: "none", cursor: "pointer", padding: 0, textAlign: "left" }}>
                  <Photo pg={pg} color={d.color} name={d.name} ratio="3/4" auto={false} />
                  <div style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 15, color: T.ink, marginTop: 8 }}>{d.name}</div>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* mobile menu */}
      {menuOpen && (
        <div style={{ position: "absolute", top: 64, left: 0, right: 0, background: T.bg,
          borderBottom: `1px solid ${T.border}`, padding: "18px 24px", display: "flex", flexDirection: "column", gap: 16 }}>
          {[["SS'26", () => { setColFilter("all"); go("collection"); }], ["Shop", () => { setColFilter("all"); go("collection"); }],
            ["Lookbook", () => go("lookbook")], ["About", () => go("about")], ["Search", onSearch]].map(([label, fn]) => (
            <button key={label} onClick={fn} style={{ ...link(false), fontSize: 15, textAlign: "left" }}>{label}</button>
          ))}
        </div>
      )}
    </nav>
  );
}

/* ── SEARCH OVERLAY ──────────────────────────────────────────────────────── */
function SearchOverlay({ open, onClose, go }) {
  const [q, setQ] = useState("");
  const results = useMemo(() => {
    const s = q.trim().toLowerCase();
    if (!s) return [];
    return DL.filter(d => d.name.toLowerCase().includes(s) || CAT_LABEL[d.cat].toLowerCase().includes(s)).slice(0, 8);
  }, [q]);
  const popular = ["Linen", "Emerald", "Lilac", "Olive", "Bralette"];
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 80, pointerEvents: open ? "auto" : "none" }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(10,10,10,0.4)",
        opacity: open ? 1 : 0, transition: "opacity .3s" }} />
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, background: T.bg, padding: "26px clamp(20px,5vw,60px) 36px",
        transform: open ? "translateY(0)" : "translateY(-100%)", transition: "transform .4s cubic-bezier(.3,.8,.3,1)" }}>
        <div style={{ maxWidth: 900, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, borderBottom: `1px solid ${T.ink}`, paddingBottom: 12 }}>
            <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search pieces…"
              style={{ flex: 1, border: "none", background: "none", outline: "none",
                fontFamily: SERIF, fontStyle: "italic", fontSize: "clamp(22px,4vw,38px)", color: T.ink }} />
            <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer",
              fontFamily: SANS, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", color: T.mid }}>Close</button>
          </div>
          {!q && (
            <div style={{ marginTop: 22 }}>
              <Label>Popular searches</Label>
              <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 12 }}>
                {popular.map(p => (
                  <button key={p} onClick={() => setQ(p)} style={{ fontFamily: SANS, fontSize: 11, letterSpacing: 1,
                    color: T.ink, background: "transparent", border: `1px solid ${T.border}`, borderRadius: 0,
                    padding: "9px 16px", cursor: "pointer" }}>{p}</button>
                ))}
              </div>
            </div>
          )}
          {q && (
            <div style={{ marginTop: 22 }}>
              <Label>{results.length} result{results.length !== 1 ? "s" : ""}</Label>
              <div className="grid-4" style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 16, marginTop: 14 }}>
                {results.map(d => (
                  <button key={d.pg} onClick={() => go("product", d.pg)} style={{ background: "none", border: "none", cursor: "pointer", padding: 0, textAlign: "left" }}>
                    <Photo pg={d.pg} color={d.color} name={d.name} ratio="3/4" auto={false} />
                    <div style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 16, color: T.ink, marginTop: 8 }}>{d.name}</div>
                    <div style={{ fontFamily: SANS, fontSize: 11, color: T.mid, marginTop: 3 }}>{peso(d.price)}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

